const { get, set, emailA, emailB, eq, call, http, login, cardPayload } = (function helpers() {
  const get = key => insomnia.environment.get(key);
  const set = (key, value) => {
    if (value === undefined || value === null) throw Error('Variável ausente: ' + key);
    insomnia.environment.set(key, value);
  };
  const emailA = get('qa_email_a');
  const emailB = get('qa_email_b');
  const base = get('origin').replace(/\/$/, '') + '/controle_ja_api/v1';
  function eq(label, value, expected) {
    insomnia.test(label, () => insomnia.expect(value).to.eql(expected));
    if (JSON.stringify(value) !== JSON.stringify(expected)) throw Error(label + ': resultado inesperado');
  }
  function call(method, path, payload, token) {
    return new Promise((resolve, reject) => {
      const header = { Accept: 'application/json' };
      if (token) header.Authorization = 'Bearer ' + token;
      const request = { url: base + path, method, header };
      if (payload !== undefined) {
        header['Content-Type'] = 'application/json';
        request.body = { mode: 'raw', raw: JSON.stringify(payload) };
      }
      insomnia.sendRequest(request, (error, response) => error ? reject(error) : resolve(response));
    });
  }
  async function http(label, status, method, path, body, token) {
    const result = await call(method, path, body, token);
    eq(label + ' — HTTP', result.code, status);
    return result;
  }
  async function login(email, label) {
    return (await http(label, 200, 'POST', '/auth', { email, password: get('qa_password') })).json().tokens;
  }
  const cardPayload = name => ({ name, totalLimit: 2000, closeDay: 10, bestDay: 15 });
  return { get, set, emailA, emailB, eq, call, http, login, cardPayload };
})();
await (async () => {
    const password = get('qa_password') || 'Qa!' + require('uuid').v4();
    set('qa_password', password);
    for (const [suffix, email] of [['A', emailA], ['B', emailB]]) {
      await http('Cadastro ' + suffix, 200, 'POST', '/users/register', { username: 'Insomnia QA ' + suffix, email, password });
      await http('Login com e-mail pendente ' + suffix, 403, 'POST', '/auth', { email, password });
    }
  })();

