await (async () => {
    const tokensA = await login(emailA, 'Login A');
    const tokensB = await login(emailB, 'Login B');
    const a = tokensA.accessToken;
    const b = tokensB.accessToken;
    set('qa_access_a_before_revocation', a);
    set('qa_access_b', b);
    const wallet = (await http('Carteira QA A', 200, 'POST', '/accounts',
      { name: 'Carteira Insomnia QA', type: 'WALLET', initialBalance: 1000 }, a)).json().id;
    const walletB = (await http('Conta padrão B', 200, 'GET', '/accounts', undefined, b)).json()[0].id;
    const category = (await http('Categoria privada A', 200, 'POST', '/categories',
      { name: 'Categoria privada QA A', categoryType: 'DESPESA' }, a)).json().id;
    const expense = (name, fields = {}) => ({ name, type: 'DESPESA', amount: 25,
      date: Date.parse('2025-01-01T12:00:00Z'), accountId: wallet, categoryId: category,
      paid: false, isFixed: false, installments: 1, ...fields });
    const transaction = (await http('Criar lançamento A', 200, 'POST', '/transactions', expense('Despesa A'), a)).json().id;
    await http('Titular consulta lançamento próprio', 200, 'GET', '/transactions/' + transaction, undefined, a);
    await http('B não consulta lançamento A', 404, 'GET', '/transactions/' + transaction, undefined, b);
    await http('B não usa categoria privada A', 400, 'POST', '/transactions', expense('Categoria alheia', { accountId: walletB }), b);
    const plan = (await http('Entitlements A', 200, 'GET', '/users/me/entitlements', undefined, a)).json();
    eq('Perfil Free', plan.plan, 'FREE');
    eq('Limite Free de dois cartões', plan.limits.creditCards, 2);
    const card = (await http('Primeiro cartão', 200, 'POST', '/cards', cardPayload('QA cartão 1'), a)).json();
    await http('Segundo cartão', 200, 'POST', '/cards', cardPayload('QA cartão 2'), a);
    const third = await http('Terceiro cartão bloqueado', 400, 'POST', '/cards', cardPayload('QA cartão 3'), a);
    eq('Mensagem de limite atingido', third.json().title, 'Limite atingido');
    const max = (await http('420 parcelas aceitas', 200, 'POST', '/transactions',
      expense('420 parcelas', { amount: 420, installments: 420 }), a)).json();
    eq('Série retornada com 420 parcelas', max.totalInstallmentsPlan, 420);
    for (const [method, path] of [['POST', '/transactions'], ['PUT', '/transactions/' + max.id]]) {
      const result = await http(method + ' com 421 parcelas', 400, method, path,
        expense('421 parcelas', { amount: 421, installments: 421 }), a);
      eq(method + ' informa o teto de 420', result.json().message, 'O número máximo de parcelas é 420');
    }
    for (const month of ['01', '02']) {
      await http('Compra de R$ 100, mês ' + month, 200, 'POST', '/transactions',
        expense('Compra QA ' + month, { accountId: card.accountId, amount: 100, date: Date.parse('2025-' + month + '-01T12:00:00Z') }), a);
    }
    const invoiceByMonth = async month => (await http('Fatura do mês ' + month, 200, 'GET',
      '/invoices/card/' + card.id + '/month/' + month + '/year/2025', undefined, a)).json().invoiceId;
    const jan = await invoiceByMonth(1);
    const feb = await invoiceByMonth(2);
    const invoice = async id => (await http('Consultar fatura', 200, 'GET', '/invoices/' + id, undefined, a)).json();
    const balance = async id => (await http('Consultar saldo', 200, 'GET', '/accounts/' + id, undefined, a)).json().currentBalance;
    const cardLimit = async () => (await http('Consultar limite disponível', 200, 'GET', '/cards', undefined, a))
      .json().find(c => c.id === card.id).currentLimit;
    await http('B não altera fatura A pela rota genérica', 404, 'PUT', '/transactions/' + jan,
      expense('Tentativa de alterar fatura', { accountId: walletB, paid: true }), b);
    await http('A usa rota própria para pagar fatura', 400, 'PUT', '/transactions/' + jan,
      expense('Alteração direta', { paid: true }), a);
    eq('Fatura A intacta', (await invoice(jan)).openAmount, 100);
    eq('Saldo inicial da carteira', await balance(wallet), 1000);
    const body = { accountId: wallet, amount: 70, paymentDate: Date.parse('2025-03-01T12:00:00Z') };
    const pay = id => call('POST', '/invoices/' + id + '/payments', body, a);
    const statuses = responses => responses.map(response => response.code).sort((x, y) => x - y);
    eq('Pagamentos concorrentes na mesma fatura', statuses(await Promise.all([pay(jan), pay(jan)])), [200, 400]);
    const paid = await invoice(jan);
    eq('R$ 30 em aberto', paid.openAmount, 30);
    eq('R$ 70 pagos', paid.paidAmount, 70);
    const credits = paid.items.filter(item => item.amount === -70);
    eq('Um único crédito de pagamento', credits.length, 1);
    const paymentId = credits[0].transactionId;
    eq('Carteira debitada uma vez', await balance(wallet), 930);
    eq('Conta do cartão creditada uma vez', await balance(card.accountId), 70);
    eq('Limite restaurado uma vez', await cardLimit(), 1870);
    const cancel = () => call('POST', '/invoices/payments/' + paymentId + '/cancel', undefined, a);
    eq('Cancelamentos concorrentes do mesmo pagamento', statuses(await Promise.all([cancel(), cancel()])), [200, 400]);
    eq('Fatura reaberta', (await invoice(jan)).openAmount, 100);
    eq('Carteira recomposta', await balance(wallet), 1000);
    eq('Conta espelho recomposta', await balance(card.accountId), 0);
    eq('Limite recomposto', await cardLimit(), 1800);
    eq('Pagamentos válidos, faturas diferentes', statuses(await Promise.all([pay(jan), pay(feb)])), [200, 200]);
    eq('Janeiro com R$ 30 em aberto', (await invoice(jan)).openAmount, 30);
    eq('Fevereiro com R$ 30 em aberto', (await invoice(feb)).openAmount, 30);
    eq('Dois débitos na carteira', await balance(wallet), 860);
    eq('Dois créditos na conta espelho', await balance(card.accountId), 140);
    eq('Dois ajustes no limite', await cardLimit(), 1940);
  })();

